use http_body_util::{BodyExt, Full, LengthLimitError, Limited};
use hyper::{
    body::{Bytes, Incoming},
    header::{self, HeaderMap, HeaderValue},
    server::conn::http1,
    service::service_fn,
    Method, Request, Response, StatusCode,
};
use hyper_util::rt::{TokioIo, TokioTimer};
use serde_json::{json, Value};
use tokio::net::{TcpListener, TcpStream};

use super::{
    app::{App, Ctx, Session},
    error::CliError,
    mcp::{
        malformed, reply, Handled, RpcError, Server, INVALID_REQUEST, LEGACY_VERSIONS,
        METHOD_NOT_FOUND, PARSE_ERROR, PROTOCOL_VERSION, UNSUPPORTED_VERSION, VERSION_KEY,
    },
    schema::Schema,
};

/// The address `--port` listens on without `--host`: this machine only.
pub const DEFAULT_HOST: &str = "127.0.0.1";
/// Request bodies larger than this are refused: tools take files by path, not content.
pub const MAX_BODY_BYTES: usize = 4 << 20;
/// `HeaderMismatch`: a header of 2026-07-28 that is missing, or not the body's value.
const HEADER_MISMATCH: i64 = -32020;

type Body = Full<Bytes>;

/// The options of `mcp` over HTTP.
pub(super) fn args(app: &App) -> [Arg; 4] {
    let prefix = app.env_prefix;
    [
        Arg::new("port")
            .long("port")
            .value_name("PORT")
            .value_parser(value_parser!(u16))
            .help("Serve over Streamable HTTP on this port, at /mcp, instead of stdio; 0 picks a free one"),
        Arg::new("host")
            .long("host")
            .value_name("ADDR")
            .requires("port")
            .help(format!(
                "The address --port listens on, 0.0.0.0 for every interface [default: {DEFAULT_HOST}]"
            )),
        Arg::new("key-from-env")
            .long("key-from-env")
            .action(ArgAction::SetTrue)
            .requires("port")
            .help(format!(
                "Serve HTTP requests without an API key with the server's credentials: --api-key, {prefix}_API_KEY, the profile"
            )),
        Arg::new("allowed-origins")
            .long("allowed-origins")
            .value_name("ORIGIN,...")
            .value_delimiter(',')
            .action(ArgAction::Append)
            .requires("port")
            .help("Serve browsers at these origins too, besides localhost's: https://app.example.com, or * for any"),
    ]
}

/// Where the server listens, and whom it serves.
#[derive(Clone, Debug)]
pub(super) struct Options {
    host: String,
    port: u16,
    key_from_env: bool,
    origins: Vec<String>,
    /// The headers an API key may come in besides `Authorization`: the spec's.
    headers: Vec<String>,
}

impl Options {
    /// The options of `--port`; `None` without it, on stdio.
    pub(super) fn new(args: &ArgMatches, schema: &Schema) -> Option<Self> {
        Some(Self {
            port: *args.get_one::<u16>("port")?,
            host: (args.get_one::<String>("host"))
                .map_or(DEFAULT_HOST, String::as_str)
                .to_owned(),
            key_from_env: args.get_flag("key-from-env"),
            origins: (args.get_many::<String>("allowed-origins").into_iter())
                .flatten()
                .map(|origin| origin.trim().trim_end_matches('/').to_owned())
                .filter(|origin| !origin.is_empty())
                .collect(),
            headers: schema.api_key_headers(),
        })
    }

    /// Whether a browser page at `origin` may call the server: localhost's, and those of
    /// `--allowed-origins`. Others are refused, which defeats DNS rebinding.
    fn allows(&self, origin: &HeaderValue) -> bool {
        let Ok(origin) = origin.to_str() else {
            return false;
        };
        let origin = origin.trim().trim_end_matches('/');
        let listed = |allowed: &String| allowed == "*" || allowed.eq_ignore_ascii_case(origin);
        if self.origins.iter().any(listed) {
            return true;
        }
        let Some(("http" | "https", rest)) = origin.split_once("://") else {
            return false;
        };
        let host = match rest.strip_prefix('[') {
            Some(v6) => v6.split(']').next(),
            None => rest.split(':').next(),
        };
        let host = host.unwrap_or_default();
        host.eq_ignore_ascii_case("localhost")
            || host.parse::<IpAddr>().is_ok_and(|ip| ip.is_loopback())
    }

    /// The API key of a request: its bearer token, else the value of the spec's API key header.
    fn key<'a>(&self, headers: &'a HeaderMap) -> Option<&'a str> {
        let bearer = headers.get(header::AUTHORIZATION).and_then(|value| {
            let (scheme, token) = value.to_str().ok()?.trim().split_once(' ')?;
            scheme.eq_ignore_ascii_case("bearer").then_some(token)
        });
        let named =
            || (self.headers.iter()).find_map(|name| headers.get(name.as_str())?.to_str().ok());
        bearer
            .or_else(named)
            .map(str::trim)
            .filter(|key| !key.is_empty())
    }
}

/// Serves HTTP until the process is stopped.
pub(super) fn serve<F, Fut>(
    server: Server,
    session: &mut Session,
    options: Options,
    dispatch: &F,
) -> Result<(), CliError>
where
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()?;
    runtime.block_on(listen(&server, session, &options, dispatch))
}

async fn listen<F, Fut>(
    server: &Server,
    session: &Session,
    options: &Options,
    dispatch: &F,
) -> Result<(), CliError>
where
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    let listener = TcpListener::bind((options.host.as_str(), options.port))
        .await
        .map_err(|error| {
            CliError::usage(format!(
                "--port: cannot listen on {}:{}: {error}",
                options.host, options.port
            ))
        })?;
    let address = listener.local_addr()?;
    let mut stderr = session.stderr.clone();
    writeln!(stderr, "{} mcp: serving http://{address}/mcp", server.name)?;
    if options.key_from_env && !address.ip().is_loopback() {
        writeln!(
            stderr,
            "warning: --key-from-env on {address}: whoever reaches it calls the API with your credentials"
        )?;
    }
    let mut connections: Vec<Pin<Box<dyn Future<Output = ()> + '_>>> = Vec::new();
    loop {
        let accepted = std::future::poll_fn(|cx| {
            connections.retain_mut(|connection| connection.as_mut().poll(cx).is_pending());
            listener.poll_accept(cx)
        })
        .await;
        match accepted {
            Ok((stream, peer)) => connections.push(Box::pin(connection(
                stream, peer, server, session, options, dispatch,
            ))),
            Err(error) if server.debug => writeln!(stderr, "debug: mcp: accept: {error}")?,
            Err(_) => {}
        }
    }
}

/// The requests of one connection, one after the other.
async fn connection<F, Fut>(
    stream: TcpStream,
    peer: SocketAddr,
    server: &Server,
    session: &Session,
    options: &Options,
    dispatch: &F,
) where
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    let service = service_fn(|request: Request<Incoming>| async move {
        let (method, path) = (request.method().clone(), request.uri().path().to_owned());
        let response = respond(request, server, session, options, dispatch).await;
        if server.debug {
            let status = response.status();
            let _ = writeln!(
                session.stderr.clone(),
                "debug: mcp: {method} {path} from {peer}: {status}"
            );
        }
        Ok::<_, Infallible>(response)
    });
    let served = http1::Builder::new()
        .timer(TokioTimer::new())
        .serve_connection(TokioIo::new(stream), service)
        .await;
    match served {
        Err(error) if server.debug => {
            let _ = writeln!(session.stderr.clone(), "debug: mcp: {peer}: {error}");
        }
        _ => {}
    }
}

/// The response to one request: `POST /mcp`, `GET /health`, else an error.
async fn respond<F, Fut>(
    request: Request<Incoming>,
    server: &Server,
    session: &Session,
    options: &Options,
    dispatch: &F,
) -> Response<Body>
where
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    let origin = request.headers().get(header::ORIGIN);
    if let Some(origin) = origin.filter(|origin| !options.allows(origin)) {
        let origin = String::from_utf8_lossy(origin.as_bytes());
        let message = format!("Forbidden: the origin {origin} is not allowed (--allowed-origins)");
        return error(StatusCode::FORBIDDEN, INVALID_REQUEST, message);
    }
    match (request.method(), request.uri().path()) {
        (&Method::POST, "/mcp") => post(request, server, session, options, dispatch).await,
        (&Method::GET, "/health") => {
            let health = json!({"status": "ok", "version": server.info()["version"]});
            json(StatusCode::OK, &health)
        }
        (_, path @ ("/mcp" | "/health")) => {
            let allow = if path == "/mcp" { "POST" } else { "GET" };
            let message = format!("Method Not Allowed: {path} takes {allow}");
            let mut response = error(StatusCode::METHOD_NOT_ALLOWED, INVALID_REQUEST, message);
            let headers = response.headers_mut();
            headers.insert(header::ALLOW, HeaderValue::from_static(allow));
            response
        }
        (_, path) => {
            let message = format!("Not Found: {path}: the MCP server is at /mcp");
            error(StatusCode::NOT_FOUND, INVALID_REQUEST, message)
        }
    }
}

/// A JSON-RPC message: its response, or 202 for a notification.
async fn post<F, Fut>(
    request: Request<Incoming>,
    server: &Server,
    session: &Session,
    options: &Options,
    dispatch: &F,
) -> Response<Body>
where
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    let (parts, body) = request.into_parts();
    let headers = &parts.headers;
    let key = options.key(headers).map(str::to_owned);
    if key.is_none() && !options.key_from_env {
        let message = match options.headers.first() {
            Some(header) => format!(
                "Unauthorized: pass the API key as Authorization: Bearer <KEY>, or {header}"
            ),
            None => "Unauthorized: pass the API key as Authorization: Bearer <KEY>".to_owned(),
        };
        let mut response = error(StatusCode::UNAUTHORIZED, INVALID_REQUEST, message);
        let challenge = HeaderValue::from_static("Bearer realm=\"mcp\"");
        (response.headers_mut()).insert(header::WWW_AUTHENTICATE, challenge);
        return response;
    }
    let content_type = headers.get(header::CONTENT_TYPE).map(HeaderValue::as_bytes);
    if content_type.is_some_and(|kind| !kind.to_ascii_lowercase().starts_with(b"application/json"))
    {
        let message = "Unsupported Media Type: the body must be application/json";
        return error(StatusCode::UNSUPPORTED_MEDIA_TYPE, INVALID_REQUEST, message);
    }
    let body = match Limited::new(body, MAX_BODY_BYTES).collect().await {
        Ok(body) => body.to_bytes(),
        Err(cause) if cause.is::<LengthLimitError>() => {
            let message = format!("Payload Too Large: more than {MAX_BODY_BYTES} bytes");
            return error(StatusCode::PAYLOAD_TOO_LARGE, INVALID_REQUEST, message);
        }
        Err(cause) => {
            let message = format!("Bad Request: {cause}");
            return error(StatusCode::BAD_REQUEST, INVALID_REQUEST, message);
        }
    };
    let message = match serde_json::from_slice::<Value>(&body) {
        Ok(message) => message,
        Err(cause) => {
            let message = format!("Parse error: {cause}");
            return error(StatusCode::BAD_REQUEST, PARSE_ERROR, message);
        }
    };
    let id = message.get("id").cloned().unwrap_or_default();
    let checked = revision(headers, &message).and_then(|version| {
        let request = !id.is_null() && message["params"].is_object();
        match request.then(|| malformed(&message["params"])).flatten() {
            Some(error) => Err(error),
            None => Ok(version),
        }
    });
    let version = match checked {
        Ok(version) => version,
        Err(cause) => return json(StatusCode::BAD_REQUEST, &reply(id, Err(cause))),
    };
    let modern = version == Some(PROTOCOL_VERSION);
    let legacy = version.filter(|version| *version != PROTOCOL_VERSION);
    let mut server = server.for_request(key.as_deref(), legacy);
    match server.handle(message, session) {
        Handled::Reply(response) => {
            let status = match response["error"]["code"].as_i64() {
                Some(_) if response["id"].is_null() => StatusCode::BAD_REQUEST,
                Some(UNSUPPORTED_VERSION) => StatusCode::BAD_REQUEST,
                Some(METHOD_NOT_FOUND) if modern => StatusCode::NOT_FOUND,
                _ => StatusCode::OK,
            };
            json(status, &response)
        }
        Handled::Start(id, call) => json(StatusCode::OK, &reply(id, Ok(call.run(dispatch).await))),
        Handled::Cancel(_) | Handled::Nothing => {
            let mut accepted = Response::new(Body::default());
            *accepted.status_mut() = StatusCode::ACCEPTED;
            accepted
        }
    }
}

/// The revision of a message, by its `MCP-Protocol-Version`, once the headers that mirror its body
/// match it: the version, `Mcp-Method` and `Mcp-Name`, which 2026-07-28 requires of requests.
/// `None` without the header, as for 2025-03-26.
fn revision(headers: &HeaderMap, message: &Value) -> Result<Option<&'static str>, RpcError> {
    let mismatch =
        |text: String| RpcError::new(HEADER_MISMATCH, format!("Header mismatch: {text}"));
    let header = |name: &str| match headers.get(name).map(HeaderValue::to_str) {
        None => Ok(None),
        Some(Ok(value)) => Ok(Some(value.trim().to_owned())),
        Some(Err(_)) => Err(mismatch(format!("{name} has invalid characters"))),
    };
    let params = &message["params"];
    let declared = params["_meta"][VERSION_KEY].as_str();
    let Some(requested) = header("mcp-protocol-version")? else {
        return match declared {
            Some(_) => Err(mismatch("MCP-Protocol-Version is missing".into())),
            None => Ok(None),
        };
    };
    let served = std::iter::once(PROTOCOL_VERSION).chain(LEGACY_VERSIONS);
    let Some(version) = served.into_iter().find(|version| *version == requested) else {
        return Err(RpcError::unsupported(requested.into()));
    };
    let modern = version == PROTOCOL_VERSION && message.get("id").is_some();
    if declared.is_some_and(|declared| declared != version) || (modern && declared.is_none()) {
        let declared = declared.unwrap_or("none");
        return Err(mismatch(format!(
            "MCP-Protocol-Version {version} does not match the body's {declared}"
        )));
    }
    let method = message["method"].as_str().unwrap_or_default();
    match header("mcp-method")? {
        Some(header) if header != method => {
            let text = format!("Mcp-Method {header} does not match the body's {method}");
            return Err(mismatch(text));
        }
        None if modern => return Err(mismatch("Mcp-Method is missing".into())),
        _ => {}
    }
    let name = params["name"].as_str().or(params["uri"].as_str());
    let named = matches!(method, "tools/call" | "resources/read" | "prompts/get");
    match header("mcp-name")?.map(decoded) {
        Some(None) => return Err(mismatch("Mcp-Name is not valid base64".into())),
        Some(Some(header)) if Some(header.as_str()) != name => {
            let name = name.unwrap_or("none");
            let text = format!("Mcp-Name {header} does not match the body's {name}");
            return Err(mismatch(text));
        }
        None if modern && named => return Err(mismatch("Mcp-Name is missing".into())),
        _ => {}
    }
    Ok(Some(version))
}

/// A header value, decoded from its `=?base64?...?=` form; `None` when that is not base64 of
/// UTF-8.
fn decoded(value: String) -> Option<String> {
    let encoded = value
        .strip_prefix("=?base64?")
        .and_then(|v| v.strip_suffix("?="));
    let Some(encoded) = encoded else {
        return Some(value);
    };
    let (mut bits, mut count, mut bytes) = (0u32, 0, Vec::new());
    for c in encoded.trim_end_matches('=').bytes() {
        let digit = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => return None,
        };
        bits = (bits << 6 | u32::from(digit)) & 0xffff;
        count += 6;
        if count >= 8 {
            count -= 8;
            bytes.push((bits >> count) as u8);
        }
    }
    String::from_utf8(bytes).ok()
}

fn json(status: StatusCode, body: &Value) -> Response<Body> {
    let mut response = Response::new(Body::new(Bytes::from(body.to_string())));
    *response.status_mut() = status;
    let kind = HeaderValue::from_static("application/json");
    response.headers_mut().insert(header::CONTENT_TYPE, kind);
    response
}

/// An HTTP error, its body a JSON-RPC error without an id.
fn error(status: StatusCode, code: i64, message: impl Into<String>) -> Response<Body> {
    json(
        status,
        &reply(Value::Null, Err(RpcError::new(code, message))),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn options(origins: &[&str], headers: &[&str]) -> Options {
        Options {
            host: DEFAULT_HOST.into(),
            port: 0,
            key_from_env: false,
            origins: origins.iter().map(|o| o.to_string()).collect(),
            headers: headers.iter().map(|h| h.to_string()).collect(),
        }
    }

    #[test]
    fn browsers_are_served_at_localhost_and_the_allowed_origins_only() {
        let allows = |options: &Options, origin: &str| {
            options.allows(&HeaderValue::from_str(origin).unwrap())
        };
        let local = options(&[], &[]);
        for origin in [
            "http://localhost:6274",
            "http://127.0.0.1",
            "https://LOCALHOST",
            "http://[::1]:3000",
            "http://127.0.0.2:80/",
        ] {
            assert!(allows(&local, origin), "{origin}");
        }
        for origin in [
            "https://evil.example",
            "http://localhost.evil.example",
            "http://127.0.0.1.nip.io",
            "null",
            "file://",
            "http://[::2]",
        ] {
            assert!(!allows(&local, origin), "{origin}");
        }
        let listed = options(&["https://app.acme.dev"], &[]);
        assert!(allows(&listed, "https://app.acme.dev"));
        assert!(!allows(&listed, "https://acme.dev"));
        assert!(allows(&options(&["*"], &[]), "https://evil.example"));
    }

    #[test]
    fn keys_come_as_bearer_tokens_or_in_the_spec_header() {
        let headers = |pairs: &[(&'static str, &'static str)]| {
            let mut map = HeaderMap::new();
            for (name, value) in pairs {
                map.insert(*name, HeaderValue::from_static(value));
            }
            map
        };
        let with_header = options(&[], &["x-api-key"]);
        let bearer = headers(&[("authorization", "bearer  sk_1 ")]);
        assert_eq!(with_header.key(&bearer), Some("sk_1"));
        let named = headers(&[("x-api-key", "sk_2"), ("authorization", "Basic YTpi")]);
        assert_eq!(with_header.key(&named), Some("sk_2"));
        assert_eq!(options(&[], &[]).key(&named), None);
        assert_eq!(
            with_header.key(&headers(&[("authorization", "Bearer ")])),
            None
        );
        assert_eq!(with_header.key(&HeaderMap::new()), None);
    }

    #[test]
    fn headers_of_2026_07_28_must_mirror_the_body() {
        let call = json!({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {
            "name": "things_list", "_meta": {
                "io.modelcontextprotocol/protocolVersion": "2026-07-28",
                "io.modelcontextprotocol/clientCapabilities": {}}}});
        let check = |pairs: &[(&'static str, &'static str)], message: &Value| {
            let mut headers = HeaderMap::new();
            for (name, value) in pairs {
                headers.insert(*name, HeaderValue::from_static(value));
            }
            revision(&headers, message).map_err(|error| {
                let error = &reply(Value::Null, Err(error))["error"];
                (
                    error["code"].as_i64().unwrap(),
                    error["message"].as_str().unwrap().to_owned(),
                )
            })
        };
        let modern = [
            ("mcp-protocol-version", "2026-07-28"),
            ("mcp-method", "tools/call"),
            ("mcp-name", "things_list"),
        ];
        assert_eq!(check(&modern, &call), Ok(Some("2026-07-28")));
        let encoded = [
            modern[0],
            modern[1],
            ("mcp-name", "=?base64?dGhpbmdzX2xpc3Q=?="),
        ];
        assert_eq!(check(&encoded, &call), Ok(Some("2026-07-28")));
        let mismatch = |text: &str| Err((HEADER_MISMATCH, format!("Header mismatch: {text}")));
        assert_eq!(
            check(
                &[modern[0], modern[1], ("mcp-name", "things_create")],
                &call
            ),
            mismatch("Mcp-Name things_create does not match the body's things_list")
        );
        assert_eq!(
            check(&[modern[0], modern[2]], &call),
            mismatch("Mcp-Method is missing")
        );
        assert_eq!(
            check(&modern[1..], &call),
            mismatch("MCP-Protocol-Version is missing")
        );
        let unsupported = check(&[("mcp-protocol-version", "1900-01-01")], &call);
        assert_eq!(unsupported.unwrap_err().0, UNSUPPORTED_VERSION);

        let legacy = json!({"jsonrpc": "2.0", "id": 1, "method": "tools/list"});
        assert_eq!(check(&[], &legacy), Ok(None));
        let header = [("mcp-protocol-version", "2025-06-18")];
        assert_eq!(check(&header, &legacy), Ok(Some("2025-06-18")));
        assert_eq!(
            check(&[modern[0]], &legacy),
            mismatch("MCP-Protocol-Version 2026-07-28 does not match the body's none")
        );
        assert_eq!(
            decoded("=?base64?SGVsbG8sIOS4lueVjA==?=".into()).unwrap(),
            "Hello, 世界"
        );
        assert_eq!(decoded("=?base64?not base64?=".into()), None);
    }
}
